from collections import defaultdict, deque

def max_potential(N, connections):
    # Initialize the network pathfinding
    max_path = defaultdict(int)
    queue = deque([(0, 0, "B")])

    while queue:
        u, balance, node = queue.popleft()

        # If balance reaches 0, it means we can power on the last connected core
        if balance == 0:
            return u

        # Explore all possible connections that are connected either directly or indirectly
        for v, flip in connections.items():
            if v == node or u == v:
                max_path[v] = max(max_path[v], max_path[u] + flip)
                queue.append((v, flip, "B"))

    return max_path.values()

