from heapq import heappush, heappop
from math import floor

def find_median(node, roads, l, r):
    # Assuming the first node is the starting junction
    if node == 1:
        return node

    count = 0
    for road in roads:
        if road[0] == node:
            count += 1
        if road[1] == node:
            count -= 1

    if count < 0:
        nodes = []
        for road in roads:
            if road[0] == node:
                heappush(nodes, road[1])
            if road[1] == node:
                heappush(nodes, road[0])
            if len(nodes) > r - floor(l / 2):
                heappop(nodes)
            if nodes:
                median = tuple(heappop(list(nodes)))[0]
                return median
    else:
        return find_median(node - 1, roads, l // 2 + 2, r - floor(l / 2))

def solve(n, l, r, roads):
    distances = [-1] * (n + 1)
    heap = [-1] * (r // 2 - l)
    if not roads:
        return r // 2

    node = 0
    for i in range(1, n + 1):
        if i < n and distances[i] == -1:
            for road in roads:
                if road[0] == i:
                    distances[road[1]] = 1
                if road[1] == i:
                    distances[road[0]] = -1

            p = 0
            if node < i:
                for j in range(p, -1, -1):
                    if distances[i] <= 0 and distances[road[j].index[-1]] <= 0:
                        break
                    p = j
            else:
                for j in range(p + 1, len(distances)):
                    if distances[i] <= 0 and distances[road[j].index[-1]] <= 0:
                        break
                    p = j

            for q in range(p, i - 1):
                if -1 < distances[i]:
                    heappush(heap, -distances[i])
                    distances[i] = 0

            for q in range(p):
                if -1 < distances[road[q].index[0]] and -1 < distances[road[q].index[1]]:
                    heappush(heap, -distances[road[q].index[0]])
                    heappush(heap, -distances[road[q].index[1]])
                    distances[road[q].index[0]] = 0
                    distances[road[q].index[1]] = 0

            heappush(heap, -distances[i])

            for j in range(i, len(distances)):
                if -1 < distances[i]:
                    heappush(heap, -distances[i])
                    distances[i] = 0

            for j in range(i):
                if i < j and -1 < distances[road[j].index[0]] and -1 < distances[road[j].index[1]]:
                    heappush(heap, -distances[road[j].index[0]])
                    heappush(heap, -distances[road[j].index[1]])
                    distances[road[j].index[0]] = 0
                    distances[road[j].index[1]] = 0

            while len(heap) > 2:
                distance = -heappop(heap)
                distances[i] = distance
                distances[floor(i / 2)] = 0

            node = i

        if len(heap) > r // 2 - floor(l / 2):
            return node

    return r // 2


