def d_sort_substring(sub, start, end, d):
    i = start % d
    j = end % d
    if i < j:
        while i < j + d:
            yield sub[i]
            i += 1
    if j < i:
        yield from d_sort_substring(sub, end - i, d - i, d)

def sort_string(s, k, d):
    for _ in range(k // d):
        for i in range(0, len(s), d):
            sub = s[i:i+d]
            sorted_sub = ''.join(sorted(sub))
            s = s[:i] + sorted_sub + s[i+d:]
    for i in range(0, len(s), d):
        if i + k > len(s):
            break
        sorted_sub = ''.join(sorted(s[i:i+k]))
        s = s[:i] + sorted_sub + s[i+k:]
    return s

