from collections import defaultdict

def find_parent(parent, node):
    if parent[node] == -1:
        return node
    return find_parent(parent, parent[node])

def union(node1, node2, parent):
    root1 = find_parent(parent, node1)
    root2 = find_parent(parent, node2)
    if root1 != root2:
        parent[root1] = root2

def calculate_disparity(parent, sizes):
    disparity = 0
    for i in range(1, len(sizes)):
        if sizes[i] == sizes[i-1]:
            disparity += sizes[i-1] - sizes[i-2]
    for i in range(1, len(sizes)):
        if sizes[i-1] > sizes[i]:
            prev_start = parent[i-2]
            current_end = parent[i-1] + 1
            current_start = parent[i-1]
            current_end = parent[i]
            while current_start < current_end and sizes[prev_start] < sizes[current_start]:
                disparity += current_start >= sizes[prev_start] and sizes[current_start] >= sizes[prev_start]
                prev_start = current_start
                current_start = parent[current_start]
            disparity -= sizes[current_start] - sizes[prev_start]
    return disparity

