def lexicographical_permutations(t, n, c, p):
    def build_rank(perm):
        return tuple(map(perm.index, accumulate(reversed(perm))))

    def find_jump(s):
        freq = defaultdict(int)
        loc = [False]
        buf = [-1]
        for i in s:
            if freq[i] or buf[-1] - loc[0] + 1 > c or loc[0] == 0:
                loc.append(i)
                buf.append(i)
                freq[i] += 1
            else:
                loc.append(loc.pop() + 1)
        return len(loc) == len(set(loc)) and not any(loc[0] in loc[1:] for loc in (0, buf))

    def get_perm(q, start, end):
        cost = 0
        if q >= 0 and build_rank(p) <= build_rank(q):
            for start, end in zip(start, end):
                cost += end - start
                if cost > c:
                    return -1
        return p[start:end]

    ranks = [build_rank(p) for _ in range(n)]
    permutations = set()
    for i, q in enumerate(ranks):
        if find_jump(q):
            continue
        for start, end in enumerate(zip(*map(ranks[i:], [ranks[:i], ranks[i+1:]]))):
            for query in range(start, end[0]+1):
                permutations.add((start, end[0], query))
    return list(permutations)

