def optimize_delivery(n, c, d, events, send_time, c_r):
    # Sort events based on time
    events.sort()

    # Initialize variables
    cost = 0
    liberties = 0
    largest_liberty = 0
    for t, p in events:
        # Determine if we need to send directly or store at Cage R
        if p == 'W':
            if liberties < largest_liberty:
                if cost + d < c_r:
                    # Cost + Delivery cost = Return cost.
                    return cost
                else:
                    cost += (c_r - cost) // d + 1
                    if cost > n:
                        smallest_acorns = c_r
                    else:
                        smallest_acorns = cost * (largest_liberty + 1)
                    largest_liberty = max(largest_liberty, cost)
                    liberties = 0
                n -= 1
            else:
                time_to_wait = abs(t - reservations[len(reservations) - 1][0]) + 1
                if c_r > (c * time_to_wait) or n > 0:
                    return c_r
                else:
                    cost += n * (largest_liberty + 1)
                    if cost > n:
                        smallest_acorns = c_r
                    else:
                        smallest_acorns = cost * (largest_liberty + 1)
                    largest_liberty = max(largest_liberty, cost)
                    liberties = 0
                n -= 1
        else:  # Little P's time
            if send_time - largest_liberty > t:
                if cost + d < c_r:
                    # Cost + Delivery cost = Return cost.
                    return cost
                else:
                    cost += (c_r - cost) // d + 1
                    if cost > n:
                        smallest_acorns = c_r
                    else:
                        smallest_acorns = cost * (largest_liberty + 1)
                    largest_liberty = max(largest_liberty, cost)
                    liberties = 0
                n -= 1
            else:
                time_to_send_and_return = t - send_time + 1
                if c_r > c * time_to_send_and_return:
                    cost += (c - c_r)
                else:
                    cost -= c_r - (c * time_to_send_and_return)
                    if cost > n:
                        smallest_acorns = c_r
                    else:
                        smallest_acorns = cost * (largest_liberty + 1)
                    largest_liberty = max(largest_liberty, cost)
                    liberties = 0
                n -= 1

            # Little P's letter delivered
            send_time = t + 1
    return smallest_acorns

