        p3 = polygon[(i + 2) % len(polygon)]
        vect1 = p2 - p1
        vect2 = p3 - p2
        angle1 = np.arccos(np.dot(vect1, vect2) / (np.linalg.norm(vect1) * np.linalg.norm(vect2)))
        angle2 = np.arccos(np.dot(vect2, vect1) / (np.linalg.norm(vect1) * np.linalg.norm(vect2)))
