from collections import defaultdict, deque

def ants_after_t_steps(n, m, t):
    meters_to_chase = defaultdict(deque)
    turn_clockwise = 0
    total_distance_chased = 0

    for i in range(n):
        start_position = i
        end_position = start_position + t % m
        meters_to_chase[start_position].append(end_position - start_position)

    for key in meters_to_chase:
        distance_to_pass = {pair[0]: pair[1] - key[0] for pair in meters_to_chase[key]}
        if distance_to_pass[min(distance_to_pass)] < 0:
            total_distance_chased += 1
            turn_clockwise += 1

        if len(key) % 2 == 0:
            destinations = [(high, low) if high > low else (low, high) for high, low in sorted(distance_to_pass.items())]
            target = destinations[turn_clockwise % len(destinations)][0]
        else:
            destinations = sorted([(high, low) for high, low in distance_to_pass.items()])
            target = destinations[turn_clockwise % len(destinations)][1]
        direction = 1 if key[1] < target else -1
        for each_chase in meters_to_chase[key]:
            if key[1] > target:
                meters_to_chase[key].remove(each_chase)
                meters_to_chase[key - direction].appendleft((each_chase + t % m) % len(meters_to_chase))

    positions = deque()
    for i in range(n):
        position = (meters_to_chase[t % m][i] + t % m) % m
        positions.append((position, meters_to_chase[t % m][i], 1))
        while len(positions) > 1:
            position = positions.popleft()

    return [p[0] for p in positions]


