from typing import List

def calculate_max_difference(tree: List[List[tuple[int, int]]], values: List[int]) -> int:
    from collections import deque

    def build_tree(edge_list: List[List[tuple[int, int]]]) -> List[List[tuple[int, int]]]:
        while len(edge_list) > 1:
            adjacency_list = []
            for u, v in edge_list:
                for pu, pv in edge_list[u]:
                    if v != pu:
                        adjacency_list.append((u, v, min(pu, pv)))
                        adjacency_list.append((v, u, min(pv, pu)))
                    adjacency_list.append((u, v, max(pu, pv)))
            edge_list = adjacency_list
        return edge_list

    def bellman_ford(graph: List[List[tuple[tuple[int, int], int]]], s: int) -> tuple[int, List[int]]:
        Q, dist = deque([(s, 0)]), [float("-inf")] * len(graph)
        dist[s] = 0
        while Q:
            curr, dist_u = Q.popleft()
            for v, w in graph[curr]:
                alt = dist_u + w
                if alt > dist[v] or graph.count((curr, v)) == 1:
                    dist[v] = alt
                    Q.append((v, alt))
        return dist

    graph = build_tree(tree)
    dist = bellman_ford(graph, 0)
    ans = 0
    for d in dist:
        ans += max(d, n - 1 - n + d)
    return ans

if __name__ == "__main__":
    n = int(input().strip())
    values = list(map(int, input().strip().split()))
    tree = [tuple(map(int, input().split())) for _ in range(n - 1)]
    print(calculate_max_difference(tree, values))
