from collections import defaultdict

def maximize_bubble_potentials(n, connections):
    graph = defaultdict(list)
    for u, v in connections:
        graph[u].append(v)
        graph[v].append(u)

    def dfs(node, visited, record):
        if node >= n:
            return 0
        if node in visited:
            return record[node]
        visited.add(node)
        potential = 0
        for neighbor in graph[node]:
            if neighbor not in visited:
                potential = max(potential, dfs(neighbor, visited, record))
        record[node] = potential + len(graph[node]) + 1
        return record[node]

    max_potential = 0
    visited = set()
    for node in range(n):
        if node not in visited:
            max_potential = max(max_potential, dfs(node, visited, {node}))
    return max_potential

