                groups.union(i, j)
    edges = []
    for i in range(n):
        for j in range(n):
            if i != j and i in groups and j in groups:
                edges.append((groups.union(i, j), (i, j)))
    edges.sort()
    count = 0
    for edge in edges:
        if not edge[1][0] in groups and not edge[1][1] in groups:
            count += 1
    return count

