def shortest_path(graph: List[List[int]], start: int, goal: int) -> int:
    """
    Returns the minimum sum of perishabilities of routes from one city to another city without revisiting any path.
    """
    # Using BFS to find the minimum perquisite of every path
    shortest_paths = {
        waypoint: {} for waypoint in range(len(graph))
    }
    for waypoint in range(len(graph)):
        shortest_paths[waypoint] = {waypoint: 0}

    queue = [(start, 0)]
    while queue:
        current, current_distance = queue.pop(0)
        for next_ in range(len(graph)):
            distance = current_distance + graph[current][next_]
            if distance < shortest_paths[next_].get(next_, float("inf")):
                shortest_paths[next_][next_] = distance
                queue.append((next_, distance))

    return shortest_paths[goal].get(goal, float("inf"))

def min_new_angela_paths(n: int, roads: List[List[int]]) -> List[int]:
    """
    Returns the minimum sum of perishabilities of routes to each city from all other cities if the signposts are set to minimize the sum.
    """
    graph = [[float("inf")] * n for _ in range(n)]
    visited = set()
    for from_city, to_route in enumerate(sorted([(-i, i) for i in range(1, len(roads) + 1)], reverse=True)):
        visited.add(from_city)
        for from_road, vec_to_city in to_route:
            if vec_to_city not in visited:
                if from_road not in visited:
                    visited.add(from_road)
                    graph[from_city][from_road] = shortest_path(graph, from_road, vec_to_city)
                graph[from_road][vec_to_city] = min(graph[from_road][vec_to_city], graph[from_city][from_road])
    distances = defaultdict(lambda: None, graph)
    return [sum(preperishability if distance and distance[i] < inf else inf for i, distance in enumerate(graph[city])) for city, preperishability in enumerate(roads)]

