        self.adj[u].append(v)
        self.adj[v].append(u)

def dijkstra(graph, src, dst):
    n = graph.n
    max_cost = [float('inf')] * n
    prev = [None] * n
    dist = [max_cost] * n

    dist[src] = 0
    for _ in range(n-1):
        u = dist.index(min(dist))
        for v in graph.adj[u]:
            if dist[u] + 1 < dist[v]:
                dist[v] = dist[u] + 1
                prev[v] = u

    cost = sum(min(a, max_cost[v]) for v, a in enumerate(dist))
    track = [0] * n

