import sys

def d_sort(s, k):
    result = []
    for i in range(0, len(s), k):
        result.append(''.join(sorted(s[i:i+k])))
    return ''.join(result)

def process_operations(shifts):
    global s, m
    for shift, d in shifts:
        s = d_sort(s[:len(s) - shift + 1], shift)
    return s

